def fib(n: int) -> int:
    """Return the n-th Fibonacci number.
    fib(10) -> 55
    fib(1) -> 1
    fib(8) -> 21
    """
    if n <= 0:
        return 0
    a, b = 0, 1
    for _ in range(1, n):
        a, b = b, a + b
    return b

Option 2: Recursive with memoization (top-down, handles larger n efficiently)
def fib(n: int) -> int:
    """Return the n-th Fibonacci number.
    fib(10) -> 55
    fib(1) -> 1
    fib(8) -> 21
    """
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def _fib(k: int) -> int:
        if k <= 0:
            return 0
        if k == 1:
            return 1
        return _fib(k - 1) + _fib(k - 2)

    return _fib(n)

Notes:
