def count_palindromes(n: int) -> int:
    """
    Count the number of palindromic integers in the range [1, n].
    """
    if n < 1:
        return 0

    s = str(n)
    length = len(s)
    count = 0

    # Count palindromes with fewer digits than n
    for l in range(1, length):
        count += 9 * (10 ** ((l - 1) // 2))

    # Count palindromes with the same number of digits as n
    prefix = int(s[:(length + 1) // 2])
    suffix = str(prefix)[::-1]

    if length % 2 == 0:
        candidate = int(str(prefix) + suffix)
    else:
        candidate = int(str(prefix) + suffix[1:])

    if candidate <= n:
        count += 1

    # Count smaller prefixes
    for p in range(1, prefix):
        if length % 2 == 0:
            candidate = int(str(p) + str(p)[::-1])
        else:
            candidate = int(str(p) + str(p)[:-1][::-1])
        count += 1

    return count

